import{config}from'./config.js';
import{safeStorage,initialiseConsent,trackCheckout}from'./tracking.js';
import{loadRuntime,translate,safeAsset}from'./site-runtime.js';
const copy={
 en:{home:'Home',title:'More ways to make a difference.',description:'Choose an ongoing gift or discover the products published by the programme.',all:'All',support:'Support',products:'Products',cart:'Cart',yourCart:'Your cart',add:'Add to cart',give:'Choose this support',monthly:'/ month',empty:'Your cart is empty.',subtotal:'Subtotal',shipping:'Delivery',total:'Total',checkout:'Secure checkout',remove:'Remove',unavailable:'Currently unavailable',digital:'Digital product',physical:'Physical product',error:'Checkout could not be opened. Please try again.',closed:'Product checkout is not open yet. Please contact the programme.',none:'No products are currently published in this category.',terms:'Read purchase terms'},
 de:{home:'Startseite',title:'Mehr Möglichkeiten, Gutes zu tun.',description:'Wählen Sie eine laufende Unterstützung oder entdecken Sie veröffentlichte Produkte.',all:'Alle',support:'Unterstützung',products:'Produkte',cart:'Warenkorb',yourCart:'Ihr Warenkorb',add:'In den Warenkorb',give:'Diese Hilfe wählen',monthly:'/ Monat',empty:'Ihr Warenkorb ist leer.',subtotal:'Zwischensumme',shipping:'Versand',total:'Gesamt',checkout:'Sicher bezahlen',remove:'Entfernen',unavailable:'Nicht verfügbar',digital:'Digitales Produkt',physical:'Physisches Produkt',error:'Checkout nicht verfügbar. Bitte erneut versuchen.',closed:'Produktzahlungen sind noch nicht geöffnet.',none:'Keine Produkte in dieser Kategorie.',terms:'Kaufbedingungen lesen'},
 fr:{home:'Accueil',title:'Encore plus de façons d’aider.',description:'Choisissez un soutien régulier ou découvrez les produits publiés par le programme.',all:'Tout',support:'Soutien',products:'Produits',cart:'Panier',yourCart:'Votre panier',add:'Ajouter au panier',give:'Choisir ce soutien',monthly:'/ mois',empty:'Votre panier est vide.',subtotal:'Sous-total',shipping:'Livraison',total:'Total',checkout:'Paiement sécurisé',remove:'Retirer',unavailable:'Indisponible',digital:'Produit numérique',physical:'Produit physique',error:'Le paiement ne peut pas s’ouvrir. Réessayez.',closed:'Les achats ne sont pas encore ouverts.',none:'Aucun produit publié dans cette catégorie.',terms:'Conditions d’achat'},
 es:{home:'Inicio',title:'Más formas de marcar la diferencia.',description:'Elige un apoyo regular o descubre los productos publicados por el programa.',all:'Todo',support:'Apoyo',products:'Productos',cart:'Carrito',yourCart:'Tu carrito',add:'Añadir al carrito',give:'Elegir este apoyo',monthly:'/ mes',empty:'Tu carrito está vacío.',subtotal:'Subtotal',shipping:'Envío',total:'Total',checkout:'Pago seguro',remove:'Eliminar',unavailable:'No disponible',digital:'Producto digital',physical:'Producto físico',error:'No se pudo abrir el pago. Inténtalo de nuevo.',closed:'La compra de productos aún no está abierta.',none:'No hay productos publicados en esta categoría.',terms:'Condiciones de compra'},
 pt:{home:'Início',title:'Mais formas de fazer a diferença.',description:'Escolha um apoio regular ou descubra os produtos publicados pelo programa.',all:'Todos',support:'Apoios',products:'Produtos',cart:'Carrinho',yourCart:'O seu carrinho',add:'Adicionar ao carrinho',give:'Escolher este apoio',monthly:'/ mês',empty:'O carrinho está vazio.',subtotal:'Subtotal',shipping:'Entrega',total:'Total',checkout:'Pagamento seguro',remove:'Remover',unavailable:'Indisponível',digital:'Produto digital',physical:'Produto físico',error:'Não foi possível abrir o pagamento. Tente novamente.',closed:'Os pagamentos de produtos ainda não estão abertos.',none:'Ainda não há produtos publicados nesta categoria.',terms:'Termos de compra'}
};
const params=new URLSearchParams(location.search);let language=[params.get('lang'),safeStorage.get('kindora-language')].find(x=>copy[x])||'en';
let products=[],settings=null,filter='all',cart=[],requestId=null;
try{const saved=JSON.parse(safeStorage.get('kindora-cart')||'null');if(saved&&Date.now()-saved.at<86400000)cart=saved.items;}catch{}
const $=id=>document.getElementById(id),t=key=>copy[language][key],money=cents=>new Intl.NumberFormat(language,{style:'currency',currency:'EUR'}).format(cents/100);
function save(){safeStorage.set('kindora-cart',JSON.stringify({items:cart,at:Date.now()}));requestId=null;renderCart();}
function setLanguage(){document.documentElement.lang=language;safeStorage.set('kindora-language',language);$('shop-language').value=language;for(const[id,key]of[['shop-home','home'],['shop-title','title'],['shop-description','description'],['cart-label','cart'],['cart-title','yourCart'],['subtotal-label','subtotal'],['shipping-label','shipping'],['total-label','total'],['cart-checkout','checkout'],['purchase-terms','terms']])$(id).textContent=t(key);document.querySelectorAll('[data-filter]').forEach(b=>b.textContent=t(b.dataset.filter));renderProducts();renderCart();}
function renderProducts(){
  $('shop-products').replaceChildren();
  for(const product of products.filter(p=>filter==='all'||(filter==='support'?p.kind.startsWith('support_'):!p.kind.startsWith('support_')))){
    const card=document.createElement('article');card.className='shop-card';const url=safeAsset(product.image_url);
    if(url){const img=document.createElement('img');img.src=url;img.alt=translate(product.title,language);img.loading='lazy';card.append(img);}
    const body=document.createElement('div');const tag=document.createElement('small');tag.textContent=product.kind==='digital'?t('digital'):product.kind==='physical'?t('physical'):t('support');const title=document.createElement('h3');title.textContent=translate(product.title,language);const p=document.createElement('p');p.textContent=translate(product.description,language);const price=document.createElement('strong');price.textContent=money(product.price_cents)+(product.kind==='support_monthly'?' '+t('monthly'):'');
    if(product.kind.startsWith('support_')){const link=document.createElement('a');link.className='button button-small';link.href=`/?plan=${product.id}&lang=${language}#donate`;link.textContent=t('give');body.append(tag,title,p,price,link);}
    else{const button=document.createElement('button');button.type='button';button.className='button button-small';button.textContent=product.stock===0?t('unavailable'):t('add');button.disabled=product.stock===0;button.addEventListener('click',()=>{const existing=cart.find(i=>i.product_id===product.id);if(existing)existing.quantity=Math.min(99,existing.quantity+1,product.stock??99);else cart.push({product_id:product.id,quantity:1});save();$('cart-dialog').showModal();});body.append(tag,title,p,price,button);}
    card.append(body);$('shop-products').append(card);
  }
  $('shop-message').textContent=$('shop-products').children.length?'':t('none');
}
function renderCart(){
  cart=cart.filter(item=>products.some(p=>p.id===item.product_id&&!p.kind.startsWith('support_')));$('cart-items').replaceChildren();let subtotal=0,physical=false;
  for(const item of cart){const product=products.find(p=>p.id===item.product_id);subtotal+=product.price_cents*item.quantity;physical ||= product.kind==='physical';const row=document.createElement('div');row.className='cart-row';const description=document.createElement('div');const title=document.createElement('strong');title.textContent=translate(product.title,language);const price=document.createElement('span');price.textContent=money(product.price_cents);description.append(title,price);const qty=document.createElement('input');qty.type='number';qty.min='1';qty.max=String(Math.min(99,product.stock??99));qty.value=item.quantity;qty.setAttribute('aria-label',translate(product.title,language));qty.addEventListener('change',()=>{item.quantity=Math.max(1,Math.min(Number(qty.max)||99,Number(qty.value)||1));save();});const remove=document.createElement('button');remove.type='button';remove.className='icon-button';remove.textContent='×';remove.setAttribute('aria-label',t('remove'));remove.addEventListener('click',()=>{cart=cart.filter(i=>i!==item);save();});row.append(description,qty,remove);$('cart-items').append(row);}
  if(!cart.length){const p=document.createElement('p');p.textContent=t('empty');$('cart-items').append(p);}
  const shipping=physical?(settings?.shipping_cents??0):0;$('cart-count').textContent=cart.reduce((n,i)=>n+i.quantity,0);$('cart-subtotal').textContent=money(subtotal);$('cart-shipping').textContent=money(shipping);$('cart-total').textContent=money(subtotal+shipping);$('cart-checkout').disabled=!cart.length;
}
$('open-cart').addEventListener('click',()=>{$('cart-dialog').showModal();});$('close-cart').addEventListener('click',()=>{$('cart-dialog').close();});$('shop-language').addEventListener('change',e=>{language=e.target.value;setLanguage();});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderProducts();}));
$('cart-checkout').addEventListener('click',async()=>{
  $('cart-error').hidden=true;if(!settings?.shop_enabled){$('cart-error').textContent=t('closed');$('cart-error').hidden=false;return;}
  $('cart-checkout').disabled=true;requestId||=crypto.randomUUID();
  try{const response=await fetch(`${config.apiBase}/shop-checkout`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:cart,locale:language,request_id:requestId}),signal:AbortSignal.timeout(25000)});const data=await response.json();if(!response.ok)throw new Error();const url=new URL(data.url);if(url.hostname!=='checkout.stripe.com'||url.protocol!=='https:')throw new Error();trackCheckout(0,'purchase');location.assign(url.href);}catch{$('cart-error').textContent=t('error');$('cart-error').hidden=false;$('cart-checkout').disabled=false;}
});
setLanguage();initialiseConsent();
try{settings=await loadRuntime();const response=await fetch(`${config.apiBase}/catalog`);const data=await response.json();products=data.products||[];setLanguage();}catch{$('shop-message').textContent=t('error');}
